(237, 1, '2025-08-19 16:30:44', '2025-08-19 08:30:44', '// Register shortcode [polylang_switcher]\r\nfunction my_polylang_switcher_shortcode($atts) {\r\n    $atts = shortcode_atts(\r\n        array(\r\n            \'dropdown\' => 0,   // 0 = list, 1 = dropdown\r\n            \'show_flags\' => 1, // 1 = show flags\r\n            \'show_names\' => 1, // 1 = show language names\r\n            \'hide_current\' => 0, // 1 = hide current language\r\n        ),\r\n        $atts,\r\n        \'polylang_switcher\'\r\n    );\r\n\r\n    // Capture output\r\n    ob_start();\r\n	echo \'<ul class=\"proz-pll\">\';\r\n    pll_the_languages(array(\r\n        \'dropdown\'      => (int) $atts[\'dropdown\'],\r\n        \'show_flags\'    => (bool) $atts[\'show_flags\'],\r\n        \'show_names\'    => (bool) $atts[\'show_names\'],\r\n        \'hide_current\'  => (bool) $atts[\'hide_current\'],\r\n    ));\r\n	echo \'</ul>\';\r\n    return ob_get_clean();\r\n}\r\nadd_shortcode(\'polylang_switcher\', \'my_polylang_switcher_shortcode\');\r\n', 'PHP - Global - Shortcodes', '', 'publish', 'closed', 'closed', '', 'php-global-shortcodes', '', '', '2025-08-19 16:31:58', '2025-08-19 08:31:58', '', 0, 'http://localhost/proz/wpcode/php-global-shortcodes/', 0, 'wpcode', '', 0),
