(454, 1, '2025-08-20 11:14:27', '2025-08-20 03:14:27', '/**\r\n * ===== Store Locator: Shortcode + AJAX + Scripts =====\r\n * Requires ACF fields on CPT \"stores\":\r\n * - area (text)\r\n * - address (textarea)\r\n * - contact_numbers (text/textarea OR repeater)\r\n * - coordinate (array with [\'lat\',\'lng\'] OR \"lat,lng\" string OR separate \'latitude\'/\'longitude\')\r\n * - country (Malaysia/Brunei)\r\n * - region (Central/Southern/Northern/East Coast/East Malaysia)\r\n * Taxonomy: \"type\" (Distributor / Preferred Dealer)\r\n */\r\n\r\n/**\r\n * Enqueue Google Maps (with Places) + frontend JS\r\n */\r\nfunction proz_store_locator_scripts() {\r\n    // Replace YOUR_API_KEY\r\n    $gmaps = add_query_arg([\r\n        \'key\'       => \'AIzaSyDTL_jpW3zjOP760_u0xHYxMQIv_fahIso\',\r\n        \'libraries\' => \'places\',\r\n    ], \'https://maps.googleapis.com/maps/api/js\');\r\n\r\n    wp_enqueue_script( \'google-maps\', $gmaps, [], _S_VERSION, true);\r\n    wp_enqueue_script( \'proz-store-locator\', get_stylesheet_directory_uri() . \'/js/store-locator.js\', [\'jquery\',\'google-maps\'], _S_VERSION, true );\r\n\r\n    $defaults = [\r\n        \'ajax_url\'      => admin_url(\'admin-ajax.php\'),\r\n        \'default_center\'=> [\'lat\' => 3.1390, \'lng\' => 101.6869],\r\n        \'default_zoom\'  => 18,\r\n        \'default_limit\' => 10,\r\n    ];\r\n    wp_localize_script(\'proz-store-locator\', \'StoreLocatorCfg\', $defaults);\r\n}\r\nadd_action(\'wp_enqueue_scripts\', \'proz_store_locator_scripts\');\r\n\r\n/**\r\n * AJAX: return stores as JSON\r\n * - Supports optional filters via GET:\r\n *   country, region, type (taxonomy), limit (int)\r\n */\r\nadd_action(\'wp_ajax_get_stores\', \'proz_get_stores_json\');\r\nadd_action(\'wp_ajax_nopriv_get_stores\', \'proz_get_stores_json\');\r\n\r\nfunction proz_get_stores_json() {\r\n    // Build WP_Query for CPT \"stores\"\r\n    $args = [\r\n        \'post_type\'      => \'stores\',\r\n        \'post_status\'    => \'publish\',\r\n        \'posts_per_page\' => -1,\r\n        \'no_found_rows\'  => true,\r\n        \'fields\'         => \'ids\',\r\n    ];\r\n\r\n    // Taxonomy filter: type\r\n    if (!empty($_GET[\'type\'])) {\r\n        $args[\'tax_query\'] = [[\r\n            \'taxonomy\' => \'type\',\r\n            \'field\'    => \'slug\',\r\n            \'terms\'    => sanitize_title($_GET[\'type\']),\r\n        ]];\r\n    }\r\n\r\n    // Meta filters: country, region\r\n    $meta_query = [\'relation\' => \'AND\'];\r\n    if (!empty($_GET[\'country\'])) {\r\n        $meta_query[] = [\r\n            \'key\'   => \'country\',\r\n            \'value\' => sanitize_text_field($_GET[\'country\']),\r\n        ];\r\n    }\r\n    if (!empty($_GET[\'region\'])) {\r\n        $meta_query[] = [\r\n            \'key\'   => \'region\',\r\n            \'value\' => sanitize_text_field($_GET[\'region\']),\r\n        ];\r\n    }\r\n    if (count($meta_query) > 1) {\r\n        $args[\'meta_query\'] = $meta_query;\r\n    }\r\n\r\n    $ids = get_posts($args);\r\n    $out = [];\r\n\r\n    foreach ($ids as $post_id) {\r\n        // ACF reads\r\n        $title   = get_the_title($post_id);\r\n        $area    = get_field(\'area\', $post_id);\r\n        $address = get_field(\'address\', $post_id);\r\n        $country = get_field(\'country\', $post_id);\r\n        $region  = get_field(\'region\', $post_id);\r\n\r\n        // contact_numbers can be: repeater, array, or text (lines separated)\r\n        $contacts = [];\r\n        $raw_contacts = get_field(\'contact_numbers\', $post_id);\r\n        if (is_array($raw_contacts)) {\r\n            // If repeater => try subfield \'number\'\r\n            foreach ($raw_contacts as $row) {\r\n                if (is_array($row) && isset($row[\'number\']) && $row[\'number\']) {\r\n                    $contacts[] = trim($row[\'number\']);\r\n                } else {\r\n                    // Or plain array of strings\r\n                    $contacts[] = is_string($row) ? trim($row) : \'\';\r\n                }\r\n            }\r\n        } elseif (is_string($raw_contacts)) {\r\n            // Split by new lines / commas\r\n            $lines = preg_split(\'/\\r\\n|\\r|\\n|,/\', $raw_contacts);\r\n            foreach ($lines as $ln) {\r\n                $ln = trim($ln);\r\n                if ($ln !== \'\') $contacts[] = $ln;\r\n            }\r\n        }\r\n\r\n        // Coordinates handling\r\n        $lat = $lng = null;\r\n        $coord = get_field(\'coordinate\', $post_id);\r\n        if (is_array($coord)) {\r\n            // ACF Google Map field or group {lat,lng}\r\n            $lat = isset($coord[\'lat\']) ? floatval($coord[\'lat\']) : null;\r\n            $lng = isset($coord[\'lng\']) ? floatval($coord[\'lng\']) : null;\r\n        } elseif (is_string($coord) && strpos($coord, \',\') !== false) {\r\n            [$latS, $lngS] = array_map(\'trim\', explode(\',\', $coord, 2));\r\n            $lat = is_numeric($latS) ? floatval($latS) : null;\r\n            $lng = is_numeric($lngS) ? floatval($lngS) : null;\r\n        }\r\n        if ($lat === null || $lng === null) {\r\n            // Fallback to separate fields if you ever used them\r\n            $lat = get_field(\'latitude\', $post_id);\r\n            $lng = get_field(\'longitude\', $post_id);\r\n            $lat = is_numeric($lat) ? floatval($lat) : null;\r\n            $lng = is_numeric($lng) ? floatval($lng) : null;\r\n        }\r\n\r\n        // Taxonomy: type (Distributor / Preferred Dealer)\r\n        $types = wp_get_post_terms($post_id, \'type\', [\'fields\' => \'names\']);\r\n        $type  = is_wp_error($types) || empty($types) ? \'\' : $types[0];\r\n\r\n        $out[] = [\r\n            \'id\'       => $post_id,\r\n            \'title\'    => $title,\r\n            \'type\'     => $type,\r\n            \'area\'     => $area,\r\n            \'address\'  => $address,\r\n            \'contacts\' => $contacts,\r\n            \'country\'  => $country,\r\n            \'region\'   => $region,\r\n            \'lat\'      => $lat,\r\n            \'lng\'      => $lng,\r\n            \'permalink\'=> get_permalink($post_id),\r\n        ];\r\n    }\r\n\r\n    // Optional: apply \'limit\' server-side (after basic filters)\r\n    $limit = isset($_GET[\'limit\']) ? max(1, intval($_GET[\'limit\'])) : 0;\r\n    if ($limit > 0 && count($out) > $limit) {\r\n        $out = array_slice($out, 0, $limit);\r\n    }\r\n\r\n    wp_send_json($out);\r\n}\r\n\r\n/**\r\n * Shortcode: [store_locator]\r\n */\r\nfunction proz_store_locator_shortcode() {\r\n    ob_start(); ?>\r\n    <div class=\"sl-controls\">\r\n        <input id=\"sl-search\" type=\"text\" placeholder=\"Search by place or address…\" />\r\n        <div class=\"sl-filter-row\">\r\n            <select id=\"sl-country\">\r\n                <option value=\"\">All Countries</option>\r\n                <option value=\"Malaysia\">Malaysia</option>\r\n                <option value=\"Brunei\">Brunei</option>\r\n            </select>\r\n            <select id=\"sl-region\">\r\n                <option value=\"\">All Regions</option>\r\n                <option value=\"Central\">Central</option>\r\n                <option value=\"Southern\">Southern</option>\r\n                <option value=\"Northern\">Northern</option>\r\n                <option value=\"East Coast\">East Coast</option>\r\n                <option value=\"East Malaysia\">East Malaysia</option>\r\n            </select>\r\n            <select id=\"sl-type\">\r\n                <option value=\"\">All Types</option>\r\n                <option value=\"Distributor\">Distributor</option>\r\n                <option value=\"Preferred Dealer\">Preferred Dealer</option>\r\n            </select>\r\n            <button id=\"sl-reset\" type=\"button\">Reset</button>\r\n        </div>\r\n        <div class=\"sl-legend\">Showing KL area by default (zoom 16) and nearest 5–10 stores.</div>\r\n    </div>\r\n\r\n    <div id=\"store-map\" style=\"width:100%; height:600px;\"></div>\r\n\r\n    <ul id=\"sl-list\" class=\"sl-list\"></ul>\r\n\r\n    <style>\r\n        .sl-controls{margin-bottom:12px}\r\n        #sl-search{width:100%;max-width:520px;padding:10px;border:1px solid #ddd;border-radius:10px}\r\n        .sl-filter-row{display:flex;gap:8px;margin-top:8px;flex-wrap:wrap}\r\n        .sl-filter-row select, .sl-filter-row button{padding:8px;border:1px solid #ddd;border-radius:10px}\r\n        .sl-legend{font-size:12px;color:#666;margin-top:6px}\r\n        #sl-list{list-style:none;padding:0;margin:12px 0 0;display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px}\r\n        #sl-list li{border:1px solid #eee;border-radius:12px;padding:10px}\r\n        #sl-list .sl-title{font-weight:600;margin-bottom:6px}\r\n        #sl-list .sl-meta{font-size:12px;color:#666}\r\n    </style>\r\n    <?php\r\n    return ob_get_clean();\r\n}\r\nadd_shortcode(\'store_locator\', \'proz_store_locator_shortcode\');\r\n', 'PHP - Shortcode - Store Locator', '', 'draft', 'closed', 'closed', '', 'php-shortcode-store-locator', '', '', '2025-08-20 11:59:02', '2025-08-20 03:59:02', '', 0, 'http://localhost/proz/wpcode/php-shortcode-store-locator/', 0, 'wpcode', '', 0),
