(461, 1, '2025-08-20 11:28:59', '2025-08-20 03:28:59', 'a:29:{s:8:\"taxonomy\";s:10:\"store-type\";s:11:\"object_type\";a:1:{i:0;s:5:\"store\";}s:22:\"advanced_configuration\";i:1;s:13:\"import_source\";s:0:\"\";s:11:\"import_date\";s:0:\"\";s:6:\"labels\";a:25:{s:4:\"name\";s:11:\"Store Types\";s:13:\"singular_name\";s:10:\"Store Type\";s:9:\"menu_name\";s:11:\"Store Types\";s:9:\"all_items\";s:15:\"All Store Types\";s:9:\"edit_item\";s:15:\"Edit Store Type\";s:9:\"view_item\";s:15:\"View Store Type\";s:11:\"update_item\";s:17:\"Update Store Type\";s:12:\"add_new_item\";s:18:\"Add New Store Type\";s:13:\"new_item_name\";s:19:\"New Store Type Name\";s:11:\"parent_item\";s:17:\"Parent Store Type\";s:17:\"parent_item_colon\";s:18:\"Parent Store Type:\";s:12:\"search_items\";s:18:\"Search Store Types\";s:9:\"most_used\";s:0:\"\";s:9:\"not_found\";s:20:\"No store types found\";s:8:\"no_terms\";s:14:\"No store types\";s:22:\"name_field_description\";s:0:\"\";s:22:\"slug_field_description\";s:0:\"\";s:24:\"parent_field_description\";s:0:\"\";s:22:\"desc_field_description\";s:0:\"\";s:14:\"filter_by_item\";s:20:\"Filter by store type\";s:21:\"items_list_navigation\";s:27:\"Store Types list navigation\";s:10:\"items_list\";s:16:\"Store Types list\";s:13:\"back_to_items\";s:21:\"← Go to store types\";s:9:\"item_link\";s:15:\"Store Type Link\";s:21:\"item_link_description\";s:22:\"A link to a store type\";}s:11:\"description\";s:0:\"\";s:12:\"capabilities\";a:4:{s:12:\"manage_terms\";s:17:\"manage_categories\";s:10:\"edit_terms\";s:17:\"manage_categories\";s:12:\"delete_terms\";s:17:\"manage_categories\";s:12:\"assign_terms\";s:10:\"edit_posts\";}s:6:\"public\";i:1;s:18:\"publicly_queryable\";i:1;s:12:\"hierarchical\";i:1;s:7:\"show_ui\";i:1;s:12:\"show_in_menu\";i:1;s:17:\"show_in_nav_menus\";i:1;s:12:\"show_in_rest\";i:1;s:9:\"rest_base\";s:0:\"\";s:14:\"rest_namespace\";s:5:\"wp/v2\";s:21:\"rest_controller_class\";s:24:\"WP_REST_Terms_Controller\";s:13:\"show_tagcloud\";i: